/**
 * Reading the context a Touchless fix step puts in the URL (DOCB-14316).
 *
 * The advice cards deep-link into settings. Landing on the right PAGE was only
 * half of it: the validation-rule catalogs are long lists, and a consultant who
 * arrives from "this field keeps failing rule X" and then has to find X by hand
 * has been given a bookmark, not an answer. So the fix step carries the
 * cluster's own facts — `?field=<field>&rule=<rule>` — and the target page
 * seeds its search box from them.
 *
 * Kept in one place because two catalogs (`ValidationRules/List.vue`,
 * `CustomValidationRules/List.vue`) have to agree on which key wins, and
 * because the value comes from a URL: anyone can type one.
 */

/** A query value as vue-router hands it over: string, repeated, or absent. */
type RouteQueryValue = string | (string | null)[] | null | undefined;

/** Longer than any real field or rule code, short enough to stay a search term. */
const MAX_TERM_LENGTH = 120;

function firstString(value: RouteQueryValue): string {
  // `?field=a&field=b` arrives as an array. The first one is the one the link
  // meant; the rest are somebody editing the URL.
  const raw = Array.isArray(value) ? value[0] : value;
  return typeof raw === 'string' ? raw.trim() : '';
}

/**
 * The term a settings list should pre-filter on, or `''` for "no deep link".
 *
 * `field` wins over `rule`: the field is what the reader recognises on the
 * card, and every catalog's search matches the field column too. Trimmed and
 * length-capped — this ends up in a filter box, so a pathological query string
 * must not become a pathological filter.
 */
export function deepLinkSearchTerm(
  query: Record<string, RouteQueryValue> | null | undefined,
): string {
  if (!query) return '';
  const term = firstString(query.field) || firstString(query.rule);
  return term.slice(0, MAX_TERM_LENGTH);
}
